#!/usr/bin/env python3
"""Offline no-CDN character showroom from original data. Does not read .prism sources."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[3]
payload=(root/'src/data/barovia-character-codex-vii.js').read_text().split('export const BAROVIA_CODEX = ',1)[1].rsplit(';',1)[0]
data=json.loads(payload)
html=r'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>BAROVIA | Character Forge VII</title>
<style>
:root{color-scheme:dark;--ink:#e7d9c4;--dim:#a99984;--line:#493c38;--blood:#c45c55;--gold:#c9aa73;--panel:#19191d;--shadow:#0d0d12;font:15px/1.48 system-ui,-apple-system,Segoe UI,sans-serif}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 52% 0%,#2b2027,#100e14 56%);color:var(--ink);min-height:100vh}button,select,input{font:inherit}button{cursor:pointer}header{padding:24px clamp(16px,4vw,54px);border-bottom:1px solid #50433b;background:linear-gradient(90deg,#1a131a,#251920)}.sigil{font:11px serif;letter-spacing:.4em;color:var(--gold)}h1{font:clamp(30px,4vw,56px) Georgia,serif;letter-spacing:.025em;margin:8px 0}header p{color:var(--dim);margin:0;max-width:730px}.ribbon{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.ribbon span{font-size:12px;border:1px solid #594944;border-radius:30px;padding:4px 9px;color:var(--gold)}main{max-width:1490px;margin:auto;padding:24px clamp(12px,3vw,35px);display:grid;grid-template-columns:minmax(275px,330px) minmax(310px,1fr) minmax(260px,340px);gap:18px;align-items:start}section,.panel{background:linear-gradient(145deg,#221d24,#18171c);border:1px solid var(--line);border-radius:14px;padding:18px;box-shadow:0 16px 32px #0003}h2{font:27px Georgia,serif;margin:0 0 7px}h3{font:21px Georgia,serif;margin:3px 0 12px}.small,.hint{font-size:12px;color:var(--dim)}.detail{font-size:14px;color:#c9b9a9}.field{display:block;margin:12px 0;font-size:12px;color:#c7b4a1}select,input[type=text],input[type=number]{width:100%;border:1px solid #5b4d4a;background:#15151b;color:var(--ink);padding:10px 11px;border-radius:7px;margin-top:5px}input:focus,select:focus{outline:2px solid #a47b65}.smallgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.smallgrid label{font-size:11px;color:var(--dim)}.smallgrid input{padding:7px;text-align:center}.tabs{display:flex;gap:5px;flex-wrap:wrap;margin:14px 0}.tab{border:1px solid #5d4844;background:#252027;color:var(--ink);border-radius:8px;padding:7px 11px}.tab.on{background:#733b3b;color:#fff;border-color:#b9736c}.card{border:1px solid #40343a;background:#17151d;border-radius:9px;padding:11px;margin:7px 0}.card b{color:#e8c38e}.card p{margin:4px 0;font-size:13px;color:#c1b4a4}.card .sub{font-size:11px;color:#b88e83}.choices{max-height:650px;overflow:auto;padding-right:3px}.choice{display:flex;gap:10px;align-items:start;padding:9px;border-bottom:1px solid #343039}.choice input{margin-top:4px;accent-color:#bf7770}.choice b{font-size:13px}.choice small{display:block;color:#9f9389}.summary{position:sticky;top:12px}.stat{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;text-align:center}.stat div{padding:8px;background:#151218;border:1px solid #493d3b;border-radius:8px}.stat strong{font:23px Georgia}.stat small{display:block;color:var(--dim)}.button{border:1px solid #8f5b58;padding:12px 13px;background:#743838;color:white;border-radius:8px;font-weight:700}.button.secondary{background:#272129;border-color:#66524b}.button:disabled{opacity:.5}.toolbar{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.error{color:#ffaaa3;font-size:12px}.ok{color:#9acb9a}.starter{display:block;width:100%;text-align:left;background:#1a171d;border:1px solid #493b37;color:var(--ink);padding:8px;border-radius:7px;margin:5px 0}.starter.active{border-color:var(--gold);background:#3b2927}.badge{display:inline-block;border:1px solid #806252;padding:2px 6px;color:#e1b67c;border-radius:40px;font-size:11px}.sep{border:0;border-top:1px solid #443a3e;margin:14px 0}.w{color:#ffb5a5}#auditResult{white-space:pre-wrap}footer{text-align:center;color:var(--dim);padding:24px;font-size:12px}@media(max-width:1100px){main{grid-template-columns:minmax(230px,.9fr) minmax(350px,1.4fr)}.summary{grid-column:1/-1;position:static}}@media(max-width:650px){main{grid-template-columns:1fr}header{padding:20px}section,.panel{padding:14px}.summary{grid-column:auto}}
</style></head><body><header><div class="sigil">DREAD DELVE • THE CHARACTER CODEX</div><h1>BAROVIA<br>THE CHARACTER FORGE</h1><p>Build a survivor for the road. Every choice has a story; some stories have teeth. Original homebrew prototype. Unreviewed rules require DM approval.</p><div class="ribbon"><span>4 NEW CLASSES</span><span>20 SUBCLASSES</span><span>8 SPECIES</span><span>12 BACKGROUNDS</span><span>48 FEATS</span><span>60 SPELLS</span></div></header>
<main><section><h2>THE SURVIVOR</h2><div class="hint">Select a starter or forge your own. Choices are stored only in this page until exported.</div><details><summary class="field" style="cursor:pointer">Twelve story starters</summary><div id="starters"></div></details><label class="field">Character name<input id="name" type="text" maxlength="70" placeholder="Who walks the Old Svalich Road?"></label><label class="field">Class<select id="className"></select></label><p id="classPitch" class="detail"></p><label class="field">Subclass<select id="subclass"></select></label><label class="field">Species<select id="species"></select></label><p id="speciesLore" class="hint"></p><label class="field">Background<select id="background"></select></label><p id="bgHook" class="hint"></p><label class="field">Level <span id="leveltext"></span><input id="level" type="range" min="1" max="20" value="1" style="width:100%;accent-color:#ac6563"></label><hr class="sep"><h3>ABILITIES</h3><div class="smallgrid" id="abilities"></div><div class="hint">Scores are editable. Origin bonuses and live battle statistics require integration with the host rules engine.</div></section>
<section><h2>THE CHOICES</h2><p class="hint" id="viewHint"></p><div class="tabs" id="tabs"><button class="tab on" data-tab="features">Progression</button><button class="tab" data-tab="spells">Spells</button><button class="tab" data-tab="feats">Feats</button><button class="tab" data-tab="catalog">Codex</button><button class="tab" data-tab="prism">Private .prism audit</button></div><div id="viewport" class="choices" aria-live="polite"></div></section>
<section class="summary"><h2>THE SHEET</h2><div id="snapshot"></div><div class="toolbar"><button class="button" id="export" type="button">Export draft JSON</button><button class="button secondary" id="reset" type="button">Reset</button></div><p class="hint">Exports a playtest draft, <b>not</b> an automatically combat-ready VTT character. Claude will review live integration and balancing separately.</p><div id="warnings"></div></section></main>
<footer>Barovia VII. Original homebrew. Your private .prism stays in your browser, never uploaded by this showroom.</footer>
<script type="application/json" id="codex">__DATA__</script>
<script>
const C=JSON.parse(document.getElementById('codex').textContent),$=q=>document.querySelector(q);let tab='features';
const AS=['Str','Dex','Con','Int','Wis','Cha'],SLOTS=[4,8,12,16,19];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const starter=i=>{const s=C.starters[i],cl=C.classes[s.className],ab={Str:12,Dex:13,Con:14,Int:10,Wis:15,Cha:8};if(cl.primary.includes('Str')){ab.Str=15;ab.Wis=14;ab.Con=13;}if(cl.primary.includes('Dex')){ab.Dex=15;ab.Wis=14;ab.Con=13;}if(cl.primary.includes('Int')){ab.Int=15;ab.Wis=13;ab.Con=14;}return{schema:'barovia-character-draft-v1',name:'',level:1,className:s.className,subclass:s.subclass,species:s.species,background:s.background,abilities:ab,skills:cl.skills.slice(0,2),feats:[],spells:[],backstory:s.hook,originName:s.name};};
let d=starter(0);
const cl=()=>C.classes[d.className],bg=()=>C.backgrounds[d.background];const maxSpell=()=>cl().casting==='full'?Math.min(9,Math.ceil(d.level/2)):cl().casting==='half'?Math.min(5,1+Math.floor((d.level-1)/4)):0;
const limits=()=>cl().casting==='full'?{cantrips:d.level>=17?5:d.level>=10?4:3,prepared:Math.min(22,d.level+3)}:cl().casting==='half'?{cantrips:d.level>=17?4:d.level>=10?3:2,prepared:Math.min(15,2+Math.floor((d.level-1)*.7))}:{cantrips:0,prepared:0};
const spells=()=>cl().casting?C.spells.filter(x=>x.classes.includes(d.className)&&x.level<=maxSpell()):[];
const featAt=(n,l)=>{let f=C.feats[n];return !!f && f.minimumLevel<=l && (f.category==='General'||f.category==='Fighting Style'||(l===19&&f.category==='Epic Boon'));};
const opts=(a,selected)=>a.map(n=>`<option ${n===selected?'selected':''} value="${esc(n)}">${esc(n)}</option>`).join('');
function validate(){let errors=[];if(d.level>=3&&C.subclasses[d.subclass]?.className!==d.className)errors.push('Choose a valid subclass.');
 let used=new Set();for(let f of d.feats){if(!featAt(f.feat,f.level)||f.level>d.level||used.has(f.level))errors.push('Invalid feat slot at '+f.level);used.add(f.level);}
 const available=new Set(spells().map(s=>s.name));if(d.spells.some(s=>!available.has(s)))errors.push('Unavailable spell chosen.');let cap=limits(),sc=C.spells.filter(s=>d.spells.includes(s.name));if(sc.filter(s=>s.level===0).length>cap.cantrips||sc.filter(s=>s.level>0).length>cap.prepared)errors.push('Too many cantrips or prepared spells.');return errors;}
function updateBasics(){let classlist=Object.keys(C.classes);$('#className').innerHTML=opts(classlist,d.className);$('#subclass').innerHTML=opts(cl().subclasses,d.subclass);$('#species').innerHTML=opts(Object.keys(C.species),d.species);$('#background').innerHTML=opts(Object.keys(C.backgrounds),d.background);$('#name').value=d.name;$('#level').value=d.level;$('#leveltext').textContent=d.level;$('#classPitch').textContent=cl().pitch;$('#speciesLore').textContent=C.species[d.species].lore;$('#bgHook').textContent='Origin feat: '+bg().feat+' • '+bg().hook;$('#abilities').innerHTML=AS.map(a=>`<label>${a}<input type="number" data-ability="${a}" min="3" max="30" value="${Number(d.abilities[a])||10}"></label>`).join('');
 $('#starters').innerHTML=C.starters.map((s,i)=>`<button class="starter ${s.name===d.originName?'active':''}" data-starter="${i}"><b>${esc(s.name)}</b><br><span class="hint">${esc(s.className)} • ${esc(s.species)}</span></button>`).join('');}
function renderContents(){const v=$('#viewport');const L=d.level;$('#tabs').querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.tab===tab));
 if(tab==='features'){let rows=[];for(let lv=1;lv<=L;lv++){for(let f of cl().features[lv]||[])rows.push({lv,...f,kind:'Class'});if(lv>=3)for(let f of C.subclasses[d.subclass].features[lv]||[])rows.push({lv,...f,kind:'Subclass'});}
 $('#viewHint').textContent=`${cl().name} • Level ${L} • ${rows.length} unlocked class and subclass features`;
 v.innerHTML=rows.map(f=>`<article class="card"><span class="sub">LEVEL ${f.lv} • ${esc(f.kind)}</span><b style="display:block">${esc(f.name)}</b><p>${esc(f.text)}</p></article>`).join('');}
 if(tab==='spells'){let all=spells(),lim=limits(),selected=C.spells.filter(s=>d.spells.includes(s.name));$('#viewHint').textContent=`Spell tiers up to ${maxSpell()}; cantrips ${selected.filter(s=>!s.level).length}/${lim.cantrips}; prepared ${selected.filter(s=>s.level).length}/${lim.prepared}. Noncombat or complex spells require a DM.`;
 v.innerHTML=all.length?all.map(s=>`<label class="choice"><input type="checkbox" data-spell="${esc(s.name)}" ${d.spells.includes(s.name)?'checked':''}><span><b>${esc(s.name)}</b> <span class="badge">${s.level||'Cantrip'}</span><small>${esc(s.school)} • ${esc(s.range)} • ${esc(s.duration)}</small><small>${esc(s.text)}</small></span></label>`).join(''):'<p class="detail">This class has no native spellcasting. Magical access requires a feat or the DM.</p>';}
 if(tab==='feats'){let html=`<article class="card"><b>Background origin feat: ${esc(bg().feat)}</b><p>${esc(C.feats[bg().feat].text)}</p></article>`;for(let l of SLOTS.filter(l=>l<=L)){let chosen=d.feats.find(f=>f.level===l)?.feat||'',options=Object.keys(C.feats).filter(n=>featAt(n,l));html+=`<div class="card"><span class="sub">LEVEL ${l} • FEAT CHOICE</span><select data-feat-level="${l}"><option value="">No feat selected</option>${opts(options,chosen)}</select>${chosen?`<p>${esc(C.feats[chosen].text)}</p>`:''}</div>`;}
 $('#viewHint').textContent='Feat choices are optional here. Ability Score Improvement remains a valid alternative in the host creator.';v.innerHTML=html;}
 if(tab==='catalog'){$('#viewHint').textContent='Browse every homebrew subclass and ancestry. These entries are not silently added to the live 5e rules.';
 v.innerHTML='<h3>Subclasses for all 12 core classes and 4 new classes</h3>'+Object.values(C.subclasses).map(s=>`<article class="card"><span class="sub">${esc(s.className)}</span><b style="display:block">${esc(s.name)}</b><p>${esc(s.pitch)}</p></article>`).join('')+'<h3>Species</h3>'+Object.values(C.species).map(s=>`<article class="card"><b>${esc(s.name)}</b><p>${esc(s.lore)}</p>${s.traits.map(t=>`<small>${esc(t.name)}: ${esc(t.text)}</small>`).join('<br>')}</article>`).join('');}
 if(tab==='prism'){$('#viewHint').textContent='Private local audit only: this file never leaves your device in the showroom.';v.innerHTML=`<div class="card"><h3>Audit your private compendium</h3><p>Choose a local .prism export. Only counts and names are shown, and no source text is added to GitHub.</p><input id="prismFile" type="file" accept=".prism,.json,application/json"><pre id="auditResult" class="hint"></pre></div>`;}
}
function summary(){const p=2+Math.floor((d.level-1)/4),hd=cl().hd,con=Math.floor((Number(d.abilities.Con)-10)/2),hp=Math.max(1,hd+con+(d.level-1)*(Math.floor(hd/2)+1+con)),warnings=validate();
 $('#snapshot').innerHTML=`<p class="hint">${esc(d.originName)} • ${esc(C.species[d.species].size)}</p><h3>${esc(d.name||'Unnamed Traveler')}</h3><p class="detail">Level ${d.level} ${esc(d.species)} ${esc(d.className)} ${d.level>=3?`(${esc(d.subclass)})`:''}<br>${esc(d.background)}</p><div class="stat"><div><strong>+${p}</strong><small>Proficiency</small></div><div><strong>d${hd}</strong><small>Hit die</small></div><div><strong>${hp}</strong><small>HP estimate</small></div></div><p class="hint">${esc(d.backstory)}</p><hr class="sep"><b>Origin: ${esc(bg().feat)}</b><p class="small">${esc(C.feats[bg().feat].text)}</p><small class="detail">${d.feats.length} extra feats • ${d.spells.length} spells • ${d.skills.length} skills</small>`;
 $('#warnings').innerHTML=warnings.length?warnings.map(w=>`<p class="error">${esc(w)}</p>`).join(''):'<p class="ok">✓ Draft choices consistent. Balance and live gameplay still require DM review.</p>';
 $('#export').disabled=!!warnings.length;}
function paint(){updateBasics();renderContents();summary();}
function changeField(k,v){d[k]=v;if(k==='className'){d.subclass=cl().subclasses[0];d.skills=cl().skills.slice(0,2);d.spells=[];d.feats=[];d.originName='Custom survivor';d.backstory='Why did you follow the road into Barovia?';const ab={Str:12,Dex:13,Con:14,Int:10,Wis:15,Cha:8};if(cl().primary.includes('Str')){ab.Str=15;ab.Wis=14;ab.Con=13;}if(cl().primary.includes('Dex')){ab.Dex=15;ab.Wis=14;ab.Con=13;}if(cl().primary.includes('Int')){ab.Int=15;ab.Wis=13;ab.Con=14;}d.abilities=ab;}if(k==='level'){d.feats=d.feats.filter(f=>f.level<=d.level);d.spells=d.spells.filter(n=>spells().some(s=>s.name===n));}paint();}
document.addEventListener('change',e=>{let t=e.target;if(['className','species','background','subclass'].includes(t.id))changeField(t.id,t.value);else if(t.id==='level')changeField('level',Number(t.value));else if(t.dataset.ability){d.abilities[t.dataset.ability]=Math.max(3,Math.min(30,Number(t.value)||10));paint();}else if(t.dataset.spell){if(t.checked&&!d.spells.includes(t.dataset.spell))d.spells.push(t.dataset.spell);else if(!t.checked)d.spells=d.spells.filter(n=>n!==t.dataset.spell);paint();}else if(t.dataset.featLevel){const l=+t.dataset.featLevel;d.feats=d.feats.filter(f=>f.level!==l);if(t.value)d.feats.push({level:l,feat:t.value});paint();}else if(t.id==='prismFile'&&t.files[0]){t.files[0].text().then(text=>{const o=JSON.parse(text),fields=['classes','races','subraces','subclasses','backgrounds','spells','feats','invocations','magicItems'],f={};for(const k of fields)f[k]=(o[k]||[]).length;f.pickableFeats=(o.feats||[]).filter(x=>x.type==='feat'||x.type==='fightingStyle').length;f.additionalClasses=(o.classes||[]).filter(x=>!(/ 2024$/.test(x.name)||['Barbarian','Bard','Cleric','Druid','Fighter','Monk','Paladin','Ranger','Rogue','Sorcerer','Warlock','Wizard'].includes(x.name))).map(x=>x.name);$('#auditResult').textContent=JSON.stringify(f,null,2);}).catch(err=>$('#auditResult').textContent=err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='name'){d.name=e.target.value;summary();}});
document.addEventListener('click',e=>{let t=e.target.closest('button');if(!t)return;if(t.dataset.starter!==undefined){d=starter(+t.dataset.starter);paint();}if(t.dataset.tab){tab=t.dataset.tab;renderContents();}if(t.id==='reset'){d=starter(0);tab='features';paint();}if(t.id==='export')try{let blob=new Blob([JSON.stringify({format:'barovia-codex-vii-draft',revision:1,requiresDMApproval:true,character:d},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=(d.name||'barovia-survivor').replace(/[^a-z0-9_-]+/gi,'-')+'-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}catch(err){alert(err.message);}});
paint();</script></body></html>'''
html=html.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))
out=root/'docs/barovia/character-forge-vii.html';out.write_text(html,encoding='utf-8')
print(out,'size',out.stat().st_size)
